#!/usr/bin/env bash
# Dev-shell runtime bootstrap, sourced by the shellHook of this repo's
# flake (./bin/dev/shell-enter.sh <PROJECT_NAME>) and of consumer flakes (shipped on PATH
# via the framework's nix package). Must be sourced (not executed): the
# .env exports must reach the interactive shell, and the MariaDB stop trap
# must bind to it. Must run from the repo root ($PWD).
#
# Loads the repo-root .env (git-ignored, generated by `make dev-init`)
# and resumes the local, isolated MariaDB daemon when its data dir exists
# but the socket is down. Nothing is exported here: without .env there is
# no data dir, so MariaDB cannot be started anyway.

if ! (return 0 2>/dev/null); then
    echo "shell-enter.sh must be sourced, not executed" >&2
    exit 1
fi

if [ -z "${1:-}" ]; then
    echo "usage: source shell-enter.sh <PROJECT_NAME>" >&2
    return 1 2>/dev/null || exit 1
fi
PROJECT_NAME="$1"

if [ -f .env ]; then
    set -a
    . ./.env
    set +a

    # Resume the local MariaDB daemon if the data dir exists but the
    # server is not running (dev-init starts it on first run).
    if [ -d "$MYSQL_DATA_DIR" ] && [ ! -S "$MYSQL_UNIX_PORT" ]; then
        echo "Starting isolated MariaDB server..."
        mysqld --datadir="$MYSQL_DATA_DIR" --pid-file="$MYSQL_PID_FILE" --socket="$MYSQL_UNIX_PORT" --skip-networking > /dev/null 2>&1 &
        MARIADB_PID=$!

        # Clean up background execution seamlessly upon exiting the shell
        trap "echo 'Stopping local MariaDB server...'; kill $MARIADB_PID; wait $MARIADB_PID 2>/dev/null" EXIT
    fi
else
    echo "No .env found - run 'make dev-init' inside this shell (required for MariaDB and runtime config)."
fi

# Inherit nix shell env in tmux (doesn't include PS1)
# Requires 'set -g default-command ...' in .tmux.conf
alias tmux="command tmux -L \$PROJECT_NAME new-session -A -s \$PROJECT_NAME"
